#include <BLEDevice.h>
#include <BLEServer.h>

const char* BT_NAMES[] = {
  "AirPods Pro Тимура",
  "AirPods Pro (украдены)",
  "Наушники из будущего",
  "Подслушиваю (шучу)",
  "AirPods Pro 3 Max Pro"
};
const int COUNT = sizeof(BT_NAMES) / sizeof(BT_NAMES[0]);

BLEAdvertising* advertising;

void setup() {
  Serial.begin(115200);
  BLEDevice::init(BT_NAMES[0]);

  advertising = BLEDevice::getAdvertising();
  advertising->setScanResponse(true);
}

void loop() {
  static int current = 0;
  static unsigned long lastChange = 0;

  if (millis() - lastChange >= 1000) {
    lastChange = millis();
    current = (current + 1) % COUNT;
    BLEDevice::init(BT_NAMES[current]);
    advertising->start();   // после переинициализации рекламу надо перезапустить
  }
}
